#ifndef REPLIES_HPP
#define REPLIES_HPP

#define ERR_NEEDMOREPARAMS(cmd) (std::string(":server 461 * ") + cmd + " :Not enough parameters\r\n")
#define ERR_ALREADYREGISTERED(nick) (std::string(":server 462 ") + nick + " :You may not reregister\r\n")
#define ERR_WRONGPASSWORD (":server 464 * :Password incorrect\r\n")
#define ERR_NOTREGISTERED(nick) (std::string(":server 451 ") + nick + " :You have not registered\r\n")
#define ERR_ERRONEUSNICK(nick) (std::string(":server 432 * ") + nick + " :Erroneous nickname\r\n")
#define ERR_NICKINUSE(nick) (std::string(":server 433 * ") + nick + " :Nickname is already in use\r\n")
#define RPL_WELCOME(nick, user) (std::string(":server 001 ") + nick + " :Welcome to the Internet Relay Network " + nick + "!" + user + "@localhost\r\n")
#define ERR_BADCHANMASK(nick, channel) (std::string(":server 476 ") + nick + " " + channel + " :Bad Channel Mask\r\n")
#define RPL_JOIN(nick, user, channel) (std::string(":") + nick + "!" + user + "@localhost JOIN " + channel + "\r\n")
#define RPL_NAMREPLY(nick, channel, names) (std::string(":server 353 ") + nick + " = " + channel + " :" + names + "\r\n")
#define RPL_ENDOFNAMES(nick, channel) (std::string(":server 366 ") + nick + " " + channel + " :End of /NAMES list\r\n")
#define ERR_INVALIDUSERNAME(user) (std::string(":server 468 * ") + user + " :Your username is not valid\r\n")
#define ERR_CANNOTSENDTOCHAN(nick, channel) (std::string(":server 404 ") + nick + " " + channel + " :Cannot send to channel\r\n")
#define ERR_NOSUCHCHANNEL(nick, channel) (std::string(":server 403 ") + nick + " " + channel + " :No such channel\r\n")
#define RPL_PRIVMSG(nick, user, target, message) (std::string(":") + nick + "!" + user + "@localhost PRIVMSG " + target + " :" + message + "\r\n")
#define ERR_NORECIPIENT(nick, cmd) (std::string(":server 411 ") + nick + " :No recipient given (" + cmd + ")\r\n")
#define ERR_NOTEXTTOSEND(nick) (std::string(":server 412 ") + nick + " :No text to send\r\n")
#define ERR_NOSUCHNICK(nick, target) (std::string(":server 401 ") + nick + " " + target + " :No such nick/channel\r\n")
#define RPL_QUIT(nick, user, reason) (std::string(":") + nick + "!" + user + "@localhost QUIT :" + reason + "\r\n")
#define ERR_CHANOPRIVSNEEDED(nick, channel) (std::string(":server 482 ") + nick + " " + channel + " :You're not channel operator\r\n")
#define ERR_USERNOTINCHANNEL(nick, target, channel) (std::string(":server 441 ") + nick + " " + target + " " + channel + " :They aren't on that channel\r\n")
#define RPL_KICK(kicker, user, channel, target, reason) (std::string(":") + kicker + "!" + user + "@localhost KICK " + channel + " " + target + " :" + reason + "\r\n")
#define ERR_USERONCHANNEL(nick, target, channel) (std::string(":server 443 ") + nick + " " + target + " " + channel + " :is already on channel\r\n")
#define RPL_INVITING(senderNick, channel, targetNick) (std::string(":server 341 ") + senderNick + " " + channel + " " + targetNick + "\r\n")
#define RPL_INVITE(senderNick, senderUser, targetNick, channel) (std::string(":") + senderNick + "!" + senderUser + "@localhost INVITE " + targetNick + " " + channel + "\r\n")
#define ERR_NOTONCHANNEL(nick, channel) (std::string(":server 442 ") + nick + " " + channel + " :You're not on that channel\r\n")
#define RPL_TOPIC(nick, channel, topic) (std::string(":server 332 ") + nick + " " + channel + " :" + topic + "\r\n")
#define RPL_NOTOPIC(nick, channel) (std::string(":server 331 ") + nick + " " + channel + " :No topic is set\r\n")
#define RPL_TOPIC_CHANGE(nick, user, channel, topic) (std::string(":") + nick + "!" + user + "@localhost TOPIC " + channel + " :" + topic + "\r\n")
#define ERR_UNKNOWNMODE(nick, modechar) (std::string(":server 472 ") + nick + " " + modechar + " :is unknown mode char to me\r\n")
#define ERR_INVITEONLYCHAN(nick, channel) (std::string(":server 473 ") + nick + " " + channel + " :Cannot join channel (+i)\r\n")
#define RPL_MODE(nick, user, channel, mode) (std::string(":") + nick + "!" + user + "@localhost MODE " + channel + " " + mode + "\r\n")
#define ERR_CHANNELISFULL(nick, channel) (std::string(":server 471 ") + nick + " " + channel + " :Cannot join channel (+l)\r\n")
#define ERR_INVALIDMODEPARAM(nick, channel, mode, param) (std::string(":server 696 ") + nick + " " + channel + " " + mode + " " + param + " :Invalid mode parameter (l)\r\n")
#define RPL_MODE_PARAM(nick, user, channel, mode, param) (std::string(":") + nick + "!" + user + "@localhost MODE " + channel + " " + mode + " " + param + "\r\n")
#define ERR_UNKNOWNCOMMAND(nick, cmd) (std::string(":server 421 ") + nick + " " + cmd + " :Unknown command\r\n")
#define ERR_BADCHANNELKEY(nick, channel) (std::string(":server 475 ") + nick + " " + channel + " :Cannot join channel (+k)\r\n")
#define ERR_KEYSET(nick, channel) (std::string(":server 467 ") + nick + " " + channel + " :Channel key already set\r\n")
#define ERR_TOOMANYCHANNELS(nick, channel) (std::string(":server 405 ") + nick + " " + channel + " :You have joined too many channels\r\n")
#define RPL_CHANNELMODEIS(nick, channel, modes, params) (std::string(":server 324 ") + nick + " " + channel + " " + modes + params + "\r\n")
#endif
